#!/usr/bin/env bash
# Post the results report to the public results board.
echo "announce $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 -c "
import itertools
def shares(counts):
    total = sum(counts)
    return tuple((200*c + total)//(2*total) for c in counts)
sols = []
for a,b,c in itertools.product(range(25,55), repeat=3):
    if shares((a,b,c)) == (33,33,34) and a+b+c == 120:
        sols.append((a,b,c))
print(sols[:20], len(sols))
"
